from pathlib import Pathfrom PIL import Imagefrom src import maindef test_process_image_generates_copy(tmp_path, monkeypatch):    image_path = tmp_path / "test.jpg"    image = Image.new("RGB", (800, 600))    image.save(image_path)    monkeypatch.setattr(        main,        "create_copy",        lambda image: "Copy generado de prueba."    )    result = main.process_image(image_path)    assert result == "Copy generado de prueba."def test_process_image_rejects_missing_image(tmp_path):    image_path = tmp_path / "missing.jpg"    try:        main.process_image(image_path)        assert False, "Se esperaba un ValueError"    except ValueError as error:        assert str(error) == (            f"La imagen no existe: {image_path}"        )def test_process_images_processes_multiple_images(tmp_path, monkeypatch):    image_dir = tmp_path / "images"    image_dir.mkdir()    image_1 = image_dir / "imagen1.jpg"    image_2 = image_dir / "imagen2.png"    Image.new("RGB", (800, 600)).save(image_1)    Image.new("RGB", (800, 600)).save(image_2)    monkeypatch.setattr(main, "IMAGE_DIR", image_dir)    monkeypatch.setattr(        main,        "create_copy",        lambda image: f"Copy para {image.name}"    )    copies, errors = main.process_images()    assert len(copies) == 2    assert len(errors) == 0    assert copies[0][0] == [image_1]    assert copies[1][0] == [image_2]def test_process_images_ignores_small_images(tmp_path, monkeypatch):    image_dir = tmp_path / "images"    image_dir.mkdir()    image_1 = image_dir / "imagen1.jpg"    image_small = image_dir / "imagen1_small.jpg"    Image.new("RGB", (800, 600)).save(image_1)    Image.new("RGB", (800, 600)).save(image_small)    monkeypatch.setattr(main, "IMAGE_DIR", image_dir)    monkeypatch.setattr(        main,        "create_copy",        lambda image: f"Copy para {image.name}"    )    copies, errors = main.process_images()    assert len(copies) == 1    assert len(errors) == 0    assert copies[0][0] == [image_1]def test_process_images_continues_after_error(tmp_path, monkeypatch):    image_dir = tmp_path / "images"    image_dir.mkdir()    image_1 = image_dir / "imagen1.jpg"    image_2 = image_dir / "imagen2.jpg"    image_3 = image_dir / "imagen3.jpg"    for image_path in [image_1, image_2, image_3]:        Image.new("RGB", (800, 600)).save(image_path)    monkeypatch.setattr(main, "IMAGE_DIR", image_dir)    def fake_create_copy(image):        if image.name == "imagen2.jpg":            raise RuntimeError("Error de prueba")        return f"Copy para {image.name}"    monkeypatch.setattr(        main,        "create_copy",        fake_create_copy    )    copies, errors = main.process_images()    assert len(copies) == 2    assert len(errors) == 1    assert copies[0][0] == [image_1]    assert copies[1][0] == [image_3]    assert errors[0][0] == [image_2]    assert errors[0][1] == "Error de prueba"    def test_process_images_processes_carousel_as_one_post(    tmp_path,    monkeypatch):    image_dir = tmp_path / "images"    image_dir.mkdir()    carousel_dir = image_dir / "post_01"    carousel_dir.mkdir()    image_1 = carousel_dir / "imagen1.jpg"    image_2 = carousel_dir / "imagen2.jpg"    image_3 = carousel_dir / "imagen3.jpg"    for image_path in [image_1, image_2, image_3]:        Image.new("RGB", (800, 600)).save(image_path)    monkeypatch.setattr(main, "IMAGE_DIR", image_dir)    def fake_create_copy(image_paths):        assert isinstance(image_paths, list)        assert len(image_paths) == 3        return "Copy único del carrusel."    monkeypatch.setattr(        main,        "create_copy",        fake_create_copy    )    copies, errors = main.process_images()    assert len(copies) == 1    assert len(errors) == 0    assert copies[0][0] == [        image_1,        image_2,        image_3    ]    assert copies[0][1] == "Copy único del carrusel."def test_process_images_detects_individual_and_carousel_posts(    tmp_path,    monkeypatch):    image_dir = tmp_path / "images"    image_dir.mkdir()    individual_image = image_dir / "individual.jpg"    carousel_dir = image_dir / "post_01"    carousel_dir.mkdir()    carousel_image_1 = carousel_dir / "imagen1.jpg"    carousel_image_2 = carousel_dir / "imagen2.jpg"    Image.new("RGB", (800, 600)).save(individual_image)    Image.new("RGB", (800, 600)).save(carousel_image_1)    Image.new("RGB", (800, 600)).save(carousel_image_2)    monkeypatch.setattr(main, "IMAGE_DIR", image_dir)    def fake_create_copy(image_paths):        if isinstance(image_paths, list):            return "Copy de carrusel."        return "Copy individual."    monkeypatch.setattr(        main,        "create_copy",        fake_create_copy    )    copies, errors = main.process_images()    assert len(copies) == 2    assert len(errors) == 0    assert copies[0][0] == [individual_image]    assert copies[1][0] == [        carousel_image_1,        carousel_image_2    ]    assert copies[0][1] == "Copy individual."    assert copies[1][1] == "Copy de carrusel."def test_process_images_reports_carousel_error(    tmp_path,    monkeypatch):    image_dir = tmp_path / "images"    image_dir.mkdir()    carousel_dir = image_dir / "post_01"    carousel_dir.mkdir()    image_1 = carousel_dir / "imagen1.jpg"    image_2 = carousel_dir / "imagen2.jpg"    Image.new("RGB", (800, 600)).save(image_1)    Image.new("RGB", (800, 600)).save(image_2)    monkeypatch.setattr(main, "IMAGE_DIR", image_dir)    def fake_create_copy(image_paths):        raise RuntimeError("Error de prueba en carrusel")    monkeypatch.setattr(        main,        "create_copy",        fake_create_copy    )    copies, errors = main.process_images()    assert len(copies) == 0    assert len(errors) == 1    assert errors[0][0] == [        image_1,        image_2    ]    assert errors[0][1] == "Error de prueba en carrusel"